document.addEventListener('DOMContentLoaded', function () {
    var buttons = document.querySelectorAll('.uc-button'); // Используем класс 'uc-button'

    buttons.forEach(function (button) {
        button.addEventListener('click', function (e) {
            e.preventDefault(); // Предотвращаем стандартное поведение

            var url = this.getAttribute('href') || 'https://t.me/EGoshev_bot?start=payment'; // Берём ссылку из href или используем дефолтную

            if (window.Telegram && window.Telegram.WebApp) {
                // Закрываем веб-приложение перед переходом
                window.Telegram.WebApp.close();
            }

            // Переход по ссылке после закрытия
            window.location.href = url;
        });
    });
});

